mapper.select:
SELECT * FROM ( SELECT po.order_no as orderNo, po.product_code as productCode, po.product_name as productName, bb.material_code as materialCode, bb.material_name as materialName, bb.material_spec as materialSpec, CASE m.material_type WHEN 'RAW' THEN '源材料' WHEN 'package_inner' THEN '内包' WHEN 'package_outer' THEN '外包' ELSE IFNULL(m.material_type, '-') END as materialTypeText, SUM(bb.planned_qty) as plannedQty, IFNULL(SUM(a.actual_qty), 0) as actualQty, ROUND(IFNULL(SUM(a.actual_qty), 0) - SUM(bb.planned_qty), 4) as diffQty, CASE WHEN SUM(bb.planned_qty) = 0 THEN NULL ELSE ROUND((IFNULL(SUM(a.actual_qty), 0) - SUM(bb.planned_qty)) / SUM(bb.planned_qty) * 100, 2) END as diffRate, po.id as orderId, bb.material_id as materialId FROM mis_production_order po INNER JOIN mis_production_batch pb ON pb.order_id = po.id AND pb.del_flag = '0' INNER JOIN mis_production_batch_bom bb ON bb.batch_id = pb.id AND bb.del_flag = '0' LEFT JOIN mis_production_batch_material_actual a ON a.batch_bom_id = bb.id AND a.del_flag = '0' LEFT JOIN mis_material m ON m.id = bb.material_id WHERE po.del_flag = '0' AND po.status IN ('1', '2', '3')
AND po.order_no LIKE CONCAT('%', #{params.orderNo}, '%')
AND po.product_code LIKE CONCAT('%', #{params.productCode}, '%')
AND bb.material_code LIKE CONCAT('%', #{params.materialCode}, '%')
AND m.material_type = #{params.materialType}
AND po.planned_start_date >= #{params.startDate}
AND po.planned_end_date <= #{params.endDate}
GROUP BY po.id, bb.material_id ) t WHERE 1=1
AND ABS(IFNULL(t.diffRate, 0)) >= #{params.diffRateThreshold}
ORDER BY t.diffRate DESC
